    def _extract_answer_from_result(self, result: dict[str, Any]) -> str:  # L1693 — real callable
        """Extract answer from ACT result.

        Real implementation is a ~24-line dict extractor with NO SDK imports
        in body. v1 claim ("LLM summarization call") is false.
        """
        if isinstance(result.get("payload"), dict):
            payload = result["payload"]
            for key in ("answer", "result", "output", "prediction", "value"):
                if key in payload:
                    val = payload[key]
                    return str(val) if val is not None else ""
        for key in ("answer", "result", "output", "prediction", "value"):
            if key in result:
                val = result[key]
                return str(val) if val is not None else ""
        return ""

